html, body { margin: 0; padding: 0; font-family: -apple-system, "PingFang SC", "Microsoft YaHei", Arial, sans-serif; }
#app { font-size: 14px; }

import { defineConfig } from 'vite'
import vue from 'vite-ng-plugin-vue2'
import path from 'path'

const srcDir = path.resolve(__dirname, '../src')
const buildDir = path.resolve(__dirname)

export default defineConfig({
  root: buildDir,
  plugins: [vue()],
  resolve: {
    alias: [
      { find: /^vuex$/, replacement: path.resolve(buildDir, 'store-stub.js') },
      { find: /^@\//, replacement: srcDir + '/' }
    ],
    extensions: ['.js', '.vue', '.json', '.scss']
  },
  build: {
    outDir: path.resolve(buildDir, 'output'),
    emptyOutDir: true,
    sourcemap: false,
    minify: false,
    target: 'es2015',
    cssCodeSplit: false,
    assetsInlineLimit: 100000000,
    rollupOptions: {
      input: path.resolve(buildDir, 'entry.js'),
      output: {
        inlineDynamicImports: true,
        format: 'iife',
        entryFileNames: 'app.js',
        chunkFileNames: 'app.js',
        assetFileNames: 'app.[ext]'
      }
    }
  }
})

const { chromium } = require('../node_modules/playwright')
const path = require('path')
;(async () => {
  const url = 'file://' + path.resolve(__dirname, 'index.html').replace(/\\/g, '/')
  const browser = await chromium.launch({ channel: 'msedge' })
  const widths = [[1536, 1100], [1366, 900]]
  for (const [w, h] of widths) {
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 })
    await page.goto(url)
    await page.waitForTimeout(600)
    const out = path.resolve(__dirname, `shot-${w}.png`)
    await page.screenshot({ path: out })
    // dump geometry of key nodes
    const geo = await page.evaluate(() => {
      const q = (s) => { const el = document.querySelector(s); if (!el) return null; const r = el.getBoundingClientRect(); return { top: Math.round(r.top), height: Math.round(r.height), bottom: Math.round(r.bottom) } }
      return {
        panel: q('.sidebar-ai-panel'),
        aiPanelRoot: q('.home-ai-panel'),
        inner: q('.home-ai-panel__inner'),
        content: q('.home-ai-panel__content'),
        cta: q('.home-ai-panel__cta'),
        robot: q('.home-ai-panel__robot'),
        notice: q('.sidebar-notice'),
        userCard: q('.user-card'),
        sidebarPanel: q('.sidebar-panel')
      }
    })
    console.log('WIDTH', w, JSON.stringify(geo, null, 2))
    await page.close()
  }
  await browser.close()
})()

