const http = require('http')
const fs = require('fs')
const path = require('path')
const root = path.resolve(__dirname)
const pub = path.resolve(__dirname, '../public')
const types = { '.js': 'text/javascript', '.css': 'text/css', '.html': 'text/html', '.png': 'image/png', '.svg': 'image/svg+xml', '.gif': 'image/gif', '.json': 'application/json' }
const srv = http.createServer((req, res) => {
  let url = decodeURIComponent(req.url.split('?')[0])
  if (url === '/') url = '/index.html'
  let file
  if (url.startsWith('/assets/')) file = path.join(pub, url)
  else if (url.startsWith('/output/')) file = path.join(root, url)
  else file = path.join(root, url)
  fs.readFile(file, (e, buf) => {
    if (e) { res.writeHead(404); res.end('nf'); return }
    res.writeHead(200, { 'Content-Type': types[path.extname(file)] || 'application/octet-stream' })
    res.end(buf)
  })
})
srv.listen(7799, () => console.log('listening 7799'))

