  const page = await browser.newPage({ viewport: { width: 1366, height: 900 }, deviceScaleFactor: 1 })
  await page.goto(url, { waitUntil: 'networkidle' }).catch(() => {})
  // wait for big gif
  await page.waitForTimeout(4000)
  const out = path.resolve(__dirname, 'shot-http.png')
  await page.screenshot({ path: out })
  const geo = await page.evaluate(() => {
    const q = (s) => { const el = document.querySelector(s); if (!el) return null; const r = el.getBoundingClientRect(); return { top: Math.round(r.top), height: Math.round(r.height), w: Math.round(r.width) } }
    const robot = document.querySelector('.home-ai-panel__robot')
    return { panel: q('.sidebar-ai-panel'), notice: q('.sidebar-notice'), robot: q('.home-ai-panel__robot'), robotNaturalW: robot && robot.naturalWidth, robotComplete: robot && robot.complete }
  })
  console.log(JSON.stringify(geo, null, 2))
  await browser.close()
})()

