const { chromium } = require('../../node_modules/playwright')
const path = require('path')
;(async () => {
  const browser = await chromium.launch({ channel: 'msedge' })
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
  const errors = []
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message))
  await page.goto('http://127.0.0.1:8092/', { waitUntil: 'networkidle', timeout: 30000 }).catch(e => errors.push('GOTO ' + e.message))
  await page.waitForTimeout(2000)
  await page.screenshot({ path: path.resolve(__dirname, 'shot-deployed.png') })
  console.log('URL:', page.url())
  console.log('ERRORS:', errors.length ? errors.slice(0,8).join('\n') : 'none')
  await browser.close()
})()
